tool_events.command:
/usr/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { normalizeTag } from './src/normalize-tag.mjs';

const observations = [];
function check(id, fn) {
  try {
    fn();
    observations.push({ id, pass: true });
  } catch (error) {
    observations.push({ id, pass: false, error: "'`${error.name}: ${error.message}` });
  }
}

check('"'all-ASCII-uppercase', () => {
  assert.equal(normalizeTag(' ABCDEFGHIJKLMNOPQRSTUVWXYZ '), 'abcdefghijklmnopqrstuvwxyz');
});
check('internal-whitespace-byte-preservation', () => {
  assert.equal(normalizeTag('\\tA  B\\tC\\nD\\r\\nE\\vF\\f'), 'a  b\\tc\\nd\\r\\ne\\vf');
});
check('unicode-trim-boundaries', () => {
  assert.equal(normalizeTag('\\uFEFF\\u00A0\\u2003TAG\\u3000\\u202F'), 'tag');
});
check('non-ASCII-case-preservation', () => {
  assert.equal(normalizeTag(' İIı Éé Ωω Ää ＡＡ Z '), 'İiı Éé Ωω Ää ＡＡ z');
});
check('empty-string-error', () => {
  assert.throws(() => normalizeTag(''), (error) => error instanceof Error && error.message === 'EMPTY_TAG');
});
check('unicode-whitespace-only-error', () => {
  assert.throws(() => normalizeTag('\\uFEFF\\u00A0\\u3000'), (error) => error instanceof Error && error.message === 'EMPTY_TAG');
});
check('non-string-domain-remains-rejected', () => {
  for (const value of [null, undefined, 42, true, Symbol('x')]) {
    assert.throws(() => normalizeTag(value), TypeError);
  }
});

console.log(JSON.stringify(observations, null, 2));
if (observations.some(({ pass }) => "'!pass)) process.exitCode = 1;
NODE'
